import{g as o,o as e,c as n,al as a}from"./chunks/framework.DmZZ3Cb1.js";const k=JSON.parse('{"title":"01 常用命令","description":"pnpm 的四条日常命令，以及用 ffmpeg 压缩、修复 mp4 的 pnpm video 脚本。","frontmatter":{"title":"01 常用命令","description":"pnpm 的四条日常命令，以及用 ffmpeg 压缩、修复 mp4 的 pnpm video 脚本。"},"headers":[],"relativePath":"notes/writing-guide/01-commands.md","filePath":"notes/writing-guide/01-commands.md","lastUpdated":1793364501000}'),t={name:"notes/writing-guide/01-commands.md"};function r(p,s,l,d,i,c){return e(),n("div",null,[...s[0]||(s[0]=[a(`<h1 id="常用命令" tabindex="-1">常用命令 <a class="header-anchor" href="#常用命令" aria-label="Permalink to &quot;常用命令&quot;">​</a></h1><p>日常只用这四条。<code>dev</code> 是边改边看，<code>preview</code> 用来验证最终构建产物。</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki css-variables vp-code" tabindex="0"><code><span class="line"><span style="color:var(--shiki-foreground);">pnpm install          # 安装依赖</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">pnpm dev              # 本地开发，默认 http://localhost:5173</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">pnpm build            # 构建，产物在 docs/.vitepress/dist</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">pnpm preview          # 预览构建产物，默认 http://localhost:4173</span></span></code></pre></div><table tabindex="0"><thead><tr><th>命令</th><th>什么时候用</th></tr></thead><tbody><tr><td><code>pnpm dev</code></td><td>写文章、改样式时的默认选择，热更新</td></tr><tr><td><code>pnpm build</code></td><td>提交前跑一次，能提前暴露链接、图片路径这类构建期错误</td></tr><tr><td><code>pnpm preview</code></td><td>只在 <code>build</code> 之后用，看的就是线上那份产物</td></tr></tbody></table><p>写完先在 <code>pnpm dev</code> 里看一眼，<code>build</code> 通过再推送。</p><h2 id="视频压缩" tabindex="-1">视频压缩 <a class="header-anchor" href="#视频压缩" aria-label="Permalink to &quot;视频压缩&quot;">​</a></h2><p>浏览器要边下边播，视频的索引（<code>moov</code>）必须在文件开头。手机或剪辑软件导出的 mp4 经常把索引放在文件尾，于是点击视频时浏览器要先跑到文件末尾取索引、再回到开头缓冲，表现就是「点了半天没反应」。</p><p><code>pnpm video</code> 做的就是重编码并加上 <code>-movflags +faststart</code>，把索引挪到开头：</p><div class="language-powershell"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki css-variables vp-code" tabindex="0"><code><span class="line"><span style="color:var(--shiki-foreground);">pnpm video                          </span><span style="color:var(--shiki-token-comment);"># 压缩 docs/public/video 下所有 mp4</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">pnpm video docs</span><span style="color:var(--shiki-token-keyword);">/</span><span style="color:var(--shiki-foreground);">public</span><span style="color:var(--shiki-token-keyword);">/</span><span style="color:var(--shiki-foreground);">video</span><span style="color:var(--shiki-token-keyword);">/</span><span style="color:var(--shiki-foreground);">a.mp4  </span><span style="color:var(--shiki-token-comment);"># 只处理单个文件</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">pnpm video </span><span style="color:var(--shiki-token-keyword);">--</span><span style="color:var(--shiki-foreground);">dry</span><span style="color:var(--shiki-token-keyword);">-</span><span style="color:var(--shiki-foreground);">run                </span><span style="color:var(--shiki-token-comment);"># 只打印计划，不动文件</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">pnpm video </span><span style="color:var(--shiki-token-keyword);">--</span><span style="color:var(--shiki-foreground);">crf </span><span style="color:var(--shiki-token-constant);">26</span><span style="color:var(--shiki-token-keyword);"> --</span><span style="color:var(--shiki-foreground);">preset medium </span><span style="color:var(--shiki-token-comment);"># 体积更小 / 速度更快</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">pnpm video </span><span style="color:var(--shiki-token-keyword);">--</span><span style="color:var(--shiki-foreground);">force                  </span><span style="color:var(--shiki-token-comment);"># 强制重压（默认跳过压过的）</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">pnpm video </span><span style="color:var(--shiki-token-keyword);">--</span><span style="color:var(--shiki-foreground);">help                   </span><span style="color:var(--shiki-token-comment);"># 全部参数</span></span></code></pre></div><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>--crf &lt;n&gt;</code></td><td>质量，默认 24；越大体积越小、画质越差</td></tr><tr><td><code>--preset &lt;name&gt;</code></td><td>编码速度，默认 <code>slow</code>；想快用 <code>medium</code></td></tr><tr><td><code>--max-height &lt;n&gt;</code></td><td>最大高度，默认 1080，超过才等比缩放</td></tr><tr><td><code>--force</code></td><td>忽略「已处理」判断，强制重压</td></tr><tr><td><code>--no-backup</code></td><td>不备份原文件</td></tr><tr><td><code>--dry-run</code></td><td>只打印计划</td></tr></tbody></table><p>脚本原地替换、文件名不变，原文件默认备份到系统临时目录。处理过的文件会写入 <code>comment=video-script</code> 标记，下次运行自动跳过，避免反复转码造成画质损失。</p><div class="rp-callout rp-callout--tip"><div class="rp-callout__title">先 dry-run 再动手</div><div class="rp-callout__content"><p><code>pnpm video</code> 是不可逆的重编码（除备份外）。先 <code>--dry-run</code> 看一眼要处理哪些文件、预计输出多大，再正式执行。</p></div></div><p>ffmpeg 不在 PATH 时，先安装或临时指定路径：</p><div class="language-powershell"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki css-variables vp-code" tabindex="0"><code><span class="line"><span style="color:var(--shiki-foreground);">winget install Gyan.FFmpeg</span></span>
<span class="line"></span>
<span class="line"><span style="color:var(--shiki-token-comment);"># 或者</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">$</span><span style="color:var(--shiki-token-constant);">env:</span><span style="color:var(--shiki-foreground);">FFMPEG_PATH</span><span style="color:var(--shiki-token-keyword);">=</span><span style="color:var(--shiki-token-string-expression);">&quot;C:\\path\\to\\ffmpeg.exe&quot;</span></span>
<span class="line"><span style="color:var(--shiki-foreground);">$</span><span style="color:var(--shiki-token-constant);">env:</span><span style="color:var(--shiki-foreground);">FFPROBE_PATH</span><span style="color:var(--shiki-token-keyword);">=</span><span style="color:var(--shiki-token-string-expression);">&quot;C:\\path\\to\\ffprobe.exe&quot;</span></span></code></pre></div>`,14)])])}const h=o(t,[["render",r]]);export{k as __pageData,h as default};
